import{_ as o,o as t,c as i,a2 as s}from"./chunks/framework.BXzK3EA4.js";const n="/assets/97cd4f92dcf51275.CJwpu3_Z.png",a="/assets/0f731e3c9d0ce28f.BoQHraPI.png",f=JSON.parse('{"title":"How to handle the \\"Permission denied, please try again\\" error when SSH logging into Linux","description":"","frontmatter":{"title":"How to handle the \\"Permission denied, please try again\\" error when SSH logging into Linux"},"headers":[],"relativePath":"operations-knowledge-base/operating-system/linux/how-to-handle-the-permission-denied-please-try-again-error-when-ssh-logging-i.md","filePath":"operations-knowledge-base/operating-system/linux/how-to-handle-the-permission-denied-please-try-again-error-when-ssh-logging-i.md","lastUpdated":1794311093000}'),r={name:"operations-knowledge-base/operating-system/linux/how-to-handle-the-permission-denied-please-try-again-error-when-ssh-logging-i.md"};function l(c,e,d,u,p,h){return t(),i("div",null,[...e[0]||(e[0]=[s('<p>Problem:</p><p>When trying to SSH into a Linux system on an ECS instance using a local SSH client, even after entering the correct password, an error message similar to the following appears:</p><ul><li>Permission denied, please try again</li><li>SSH server denied password, please try again.</li></ul><p>Reasons:</p><ol><li>Root user login disabled within the ECS instance: The SSH service configuration file <code>/etc/ssh/sshd\\_config</code> has the <code>PermitRootLogin</code> or <code>PasswordAuthentication</code> parameter set to &quot;no&quot;.</li></ol><p>You can refer to the following solution for the issue caused by disabling root user login:</p><ol start="2"><li>SELinux service enabled on the Linux system, preventing both root and regular users from logging in.</li></ol><p>Execute <code>cat /var/log/secure</code> to view the <code>secure</code> log. If the log contains <code>error: Could not get shadow information for root. </code>, it indicates that SELinux service is enabled.</p><p>You can refer to the following solution for the issue caused by SELinux service:</p><p>Solution:</p><ol><li><p>Solution for the issue caused by disabling root user login:</p></li><li><p>Log in using VNC.</p></li><li><p>Check the configuration of the <code>PermitRootLogin</code> or <code>PasswordAuthentication</code> parameter in <code>/etc/ssh/sshd\\_config</code>.</p></li></ol><ul><li>#cat /etc/ssh/sshd_config</li></ul><p>As shown in the following figure, when the <code>PermitRootLogin</code> and <code>PasswordAuthentication</code> parameters are set to &quot;no&quot;, it means that root user login is disabled, and password authentication is also disabled.</p><p><img src="'+n+'" alt=""></p><p>3.Modify the configuration of <code>PermitRootLogin</code> and <code>PasswordAuthentication</code> according to your business requirements.</p><p>Open the SSH configuration file:</p><ul><li>vi /etc/ssh/sshd_config</li></ul><p>4.Modify the values of the <code>PermitRootLogin</code> and <code>PasswordAuthentication</code> parameters:</p><ul><li>If you want to allow root user login, set the value of <code>PermitRootLogin</code> to &quot;yes&quot;.</li><li>If you want to allow password authentication, set the value of <code>PasswordAuthentication</code> to &quot;yes&quot;.</li></ul><p><img src="'+a+'" alt=""></p><p>5.Press the Esc key, then type &quot;:wq&quot; to save the changes and exit.</p><p>6.Execute the following command to restart the SSH service:</p><ul><li>systemctl restart sshd.service</li></ul><ol start="2"><li>Solution for SELinux service causing the issue</li></ol><p>You can choose to temporarily or permanently disable the SELinux service based on your specific situation to resolve the SSH connection issue.</p><p>To check the SELinux service status:</p><ol><li><p>Log in to the ECS instance using VNC.</p></li><li><p>Execute the following command to view the current SELinux service status:</p></li></ol><ul><li>/usr/sbin/sestatus -v</li></ul><p>The system displays something like the following:</p><p>SELinux status: enabled</p><p>SELinux status The parameter values are explained as follows:</p><p>enabled: SELinux service is enabled</p><p>disabled: SELinux service is disabled</p><p>3.Disable SELinux service.</p><p>Disabling SELinux temporarily will be effective until the system is rebooted.</p><p>Temporarily disable SELinux by executing the following command.</p><ul><li>setenforce 0</li></ul><p>To permanently disable SELinux, execute the following command:</p><ul><li>sed -i &#39;s/SELINUX=enforcing/SELINUX=disabled/&#39; /etc/selinux/config</li></ul><p>Please note that this command is applicable only when the current SELinux status is set to &quot;enforcing&quot;.</p><p>4.Restart the instance for the changes to take effect.</p>',41)])])}const m=o(r,[["render",l]]);export{f as __pageData,m as default};
